toad_implementation.code_blueprint:
canvas {
  size: 700px 920px;
  fill: #1A1513;
  font-family: "Playfair Display, serif";
}

>darkWood = #1A1513;
>saffronRed = #C44521;
>warmCreme = #F7EFE2;
>herbGreen = #556B2F;
>goldDivider = #B8860B;

rect #menuCard {
  at: center of canvas;
  size: 600px 820px;
  fill: #221C1A;
  stroke: >goldDivider;
  stroke-width: 1px;
}

text #restaurantName {
  at: top center of #menuCard offset 0px 48px;
  content: "L ' A R D O I S E";
  font-size: 26px;
  font-weight: 600;
  color: >warmCreme;
}

text #menuType {
  at: below #restaurantName offset 10px;
  content: "MENU DÉGUSTATION DU CHEF";
  font-size: 11px;
  color: >goldDivider;
}

circle #plateVisual {
  at: below #menuType offset 40px;
  size: 200px;
  fill: #2B2421;
  stroke: >saffronRed;
  stroke-width: 2px;
}

circle #plateInnerRim {
  at: center of #plateVisual;
  size: 150px;
  fill: none;
  stroke: >warmCreme;
  stroke-width: 1px;
}

text #courseTitle {
  at: below #plateVisual offset 48px;
  content: "SAINT-JACQUES POÊLÉES";
  font-size: 18px;
  font-weight: 600;
  color: >warmCreme;
}

text #courseDescription {
  at: below #courseTitle offset 8px;
  size: 440px;
  content: "Jakobsmuscheln an Safran-Emulsion, wildem Fenchel und geröstetem Buchweizen.";
  font-size: 12px;
  color: #BDB4A8;
}

text #winePairing {
  at: below #courseDescription offset 16px;
  content: "Accord Mets & Vins: Meursault Premier Cru 2021";
  font-size: 11px;
  color: >herbGreen;
}
